if(!isUser())redirect('/?action=login');$project=ModuleProjectAccess::select($_GET['project']??$_SESSION['project_id']??'');
if(!canAccessManagement()||(!AiAccess::pageAllowed()&&!canAccessFeature('settings','view')&&!canAccessFeature('wp_crm','view')&&!canAccessFeature('extract','view')))AccessControl::deny();
$store=new AiStore();$principal=AiAccess::principal($project);$pid=$project['id'];$message='';$error='';
if(isset($_GET['download'])){try{$kind=$_GET['download'];$bytes=ConnectionDownloads::package($project,$kind);header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="maarksho-'.$kind.'-1.1.0.zip"');header('X-Content-Type-Options: nosniff');echo $bytes;exit;}catch(Throwable $e){http_response_code(403);$error='دانلود این بسته مجاز یا در دسترس نیست.';}}
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){RequestSecurity::enforce();try{if(($_POST['action']??'')!=='probe_api')throw new RuntimeException('عملیات معتبر نیست.');$result=(new AiReports($store))->probe($principal,$_POST['provider']??'');if(!$result['success'])throw new RuntimeException($result['error']);$message=$result['note'];}catch(Throwable $e){http_response_code(422);$error=$e instanceof RuntimeException?$e->getMessage():'تست اتصال ناموفق بود.';}}
$catalog=(new ProjectConnections($store))->catalog($project);$providers=AiAccess::pageAllowed()?(new AiReports($store))->providers($principal):[];
function cn_h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function cn_time($v){if(!$v)return 'هنوز دریافت نشده';return is_numeric($v)?formatPersianDate((int)$v,'Y/m/d H:i'):cn_h($v);}
