<div class="cn-grid"><?php foreach($catalog['connections'] as $connection):?><section class="cn-card" data-connection="<?=cn_h($connection['id'])?>"><div class="cn-card-head"><span class="cn-symbol"><?=cn_h(strtoupper(substr($connection['id'],0,2)))?></span><span class="cn-state"><?=$connection['configured']?'تنظیمات موجود است':'در انتظار اتصال کاربر'?></span></div><h2><?=cn_h($connection['title'])?></h2><p><?=cn_h($connection['note'])?></p><dl><div><dt>تست خواندن معتبر</dt><dd><?=$connection['authorized']?'تأیید شده':'تأیید نشده'?></dd></div><div><dt>آخرین دریافت داده</dt><dd><?=cn_time($connection['last_received'])?></dd></div><?php if(isset($connection['last_complete'])):?><div><dt>تکمیل اخیر دریافت</dt><dd><?=cn_time($connection['last_complete'])?></dd></div><?php endif;?></dl><?php if(!empty($connection['error'])):?><p class="cn-error" role="alert"><?=cn_h($connection['error'])?></p><?php endif;?><a class="cn-button" href="<?=cn_h($connection['url'])?>">تنظیم، راهنما و تست ←</a><?php if(!empty($connection['sources'])):?><details><summary>منابع و وضعیت دریافت</summary><?php foreach($connection['sources'] as $source):?><p><?=cn_h($source['name'])?> · <?=$source['enabled']?'فعال':'متوقف'?> · <?=cn_time($source['last_received'])?><?php if($source['last_error']):?><br><?=cn_h($source['last_error'])?><?php endif;?></p><?php endforeach;?></details><?php endif;?></section><?php endforeach;?></div>
